// PHS CDP — PII Masking Transformation
// Applied to: Facebook Pixel, GA4, CleverTap, OneSignal, External Webhooks
// NOT applied to: BFF Webhook (internal), Mautic (internal)

function maskEmail(email) {
  if (!email) return undefined;
  const [local, domain] = email.split('@');
  if (!domain) return '***@***.***';
  return local.charAt(0) + '***@' + domain;
}

function maskPhone(phone) {
  if (!phone) return undefined;
  const digits = String(phone).replace(/\D/g, '');
  if (digits.length < 4) return '***';
  return digits.slice(0, 2) + '***' + digits.slice(-2);
}

function maskName(name) {
  if (!name) return undefined;
  const parts = String(name).split(' ');
  return parts.map((p, i) => i === 0 ? p.charAt(0) + '***' : '***').join(' ');
}

function hashValue(val) {
  // Simple hash indicator — in production use SHA256
  if (!val) return undefined;
  return '[HASHED]';
}

export function transformEvent(event) {
  // Deep clone to avoid mutation
  const e = JSON.parse(JSON.stringify(event));

  // Mask identify traits
  if (e.traits) {
    if (e.traits.email) e.traits.email = maskEmail(e.traits.email);
    if (e.traits.phone) e.traits.phone = maskPhone(e.traits.phone);
    if (e.traits.mobile) e.traits.mobile = maskPhone(e.traits.mobile);
    if (e.traits.name) e.traits.name = maskName(e.traits.name);
    if (e.traits.firstName) e.traits.firstName = e.traits.firstName.charAt(0) + '***';
    if (e.traits.lastName) e.traits.lastName = '***';
    // Remove sensitive financial fields
    delete e.traits.id_number;
    delete e.traits.passport_number;
    delete e.traits.bank_account;
    delete e.traits.balance;
    delete e.traits.portfolio_value;
  }

  // Mask context.traits as well
  if (e.context && e.context.traits) {
    if (e.context.traits.email) e.context.traits.email = maskEmail(e.context.traits.email);
    if (e.context.traits.phone) e.context.traits.phone = maskPhone(e.context.traits.phone);
    if (e.context.traits.name) e.context.traits.name = maskName(e.context.traits.name);
  }

  // For track events, remove any PII accidentally in properties
  if (e.properties) {
    if (e.properties.email) e.properties.email = maskEmail(e.properties.email);
    if (e.properties.phone) e.properties.phone = maskPhone(e.properties.phone);
    // Keep non-PII properties intact (stock codes, product names, etc.)
  }

  // Remove userId for anonymous tracking to external (use anonymousId only)
  // Uncomment if strict privacy required:
  // delete e.userId;

  return e;
}
